`;
    document.head.appendChild(style);
  }

  function renderDashboard() {
    const panel = document.getElementById("df-dashboard-panel");
    if (!panel) return;

    if (metrics.length === 0 && charts.length === 0) {
      panel.innerHTML = `
        <div class="df-empty-state">
          <div class="df-empty-state-icon">??</div>
          <div class="df-empty-state-title">No Dashboard Data Available</div>
          <div class="df-empty-state-text">Please select filters and click "Apply Filters" to view dashboard metrics and charts.</div>
        </div>`;
      return;
    }

    let html = '<div class="df-dashboard-content">';

    if (metrics.length) {
      html += '<div class="df-metrics-container">';
      for (const m of metrics) {
        html += `
          <div class="df-metric-card">
            ${m.icon ? `<div class="df-metric-icon">${escapeHTML(m.icon)}</div>` : ''}
            <div class="df-metric-title">${escapeHTML(m.title)}</div>
            <div class="df-metric-value">${escapeHTML(formatValue(m.value))}</div>
          </div>`;
      }
      html += "</div>";
    }

    if (charts.length) {
      html += '<div class="df-charts-container">';
      for (const c of charts) {
        const className = c.fullWidth ? "df-chart-card df-chart-full" : "df-chart-card";
        html += `
          <div class="${className}">
            <div class="df-chart-title">${escapeHTML(c.name)}</div>
            <div id="df-${c.id}" class="df-chart-container"></div>
          </div>`;
      }
      html += "</div>";
    }

    html += "</div>";
    panel.innerHTML = html;

    setTimeout(() => {
      for (const c of charts) {
        try {
          renderChart(c);
        } catch (e) {
          console.error("Chart render error:", c && c.name, e);
        }
      }
    }, 100);
  }

  function renderChart(chart) {
    if (typeof Plotly === "undefined") {
      console.error("Plotly not loaded");
      return;
    }

    const containerId = `df-${chart.id}`;
    const container = document.getElementById(containerId);
    if (!container) return;

    const baseLayout = {
      margin: { t: 20, r: 20, b: 50, l: 50 },
      paper_bgcolor: "rgba(255,255,255,0)",
      plot_bgcolor: "rgba(248,250,252,0.5)",
      font: { 
        family: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif", 
        size: 12, 
        color: "#1a202c" 
      },
      showlegend: chart.type === "pie" || !!chart.series,
      hovermode: "closest",
      xaxis: { 
        showgrid: false, 
        showline: true, 
        linecolor: "#e2e8f0", 
        linewidth: 2,
        tickfont: { size: 11 },
        automargin: true
      },
      yaxis: { 
        showgrid: true, 
        gridcolor: "rgba(226,232,240,0.6)", 
        showline: false, 
        zeroline: true, 
        zerolinecolor: "#cbd5e0",
        tickfont: { size: 11 },
        automargin: true
      },
      legend: { 
        orientation: "h", 
        x: 0, 
        y: -0.15, 
        bgcolor: "rgba(255,255,255,0.9)", 
        bordercolor: "#e2e8f0", 
        borderwidth: 1,
        font: { size: 11 }
      },
      autosize: true,
      height: null
    };

    let plotlyData;

    switch (chart.type) {
      case "line":
        plotlyData = chart.series
          ? chart.series.map((s, idx) => ({
              x: chart.xAxis,
              y: s.values,
              type: "scatter",
              mode: "lines+markers",
              name: s.name,
              line: { width: 3, shape: "spline" },
              marker: { size: 8 },
              fill: idx === 0 ? "tozeroy" : undefined,
              fillcolor: idx === 0 ? `${config.primaryColor}15` : undefined,
            }))
          : [
              {
                x: chart.labels,
                y: chart.values,
                type: "scatter",
                mode: "lines+markers",
                line: { color: config.primaryColor, width: 3, shape: "spline" },
                marker: { size: 8, color: config.accentColor, line: { width: 2, color: "white" } },
                fill: "tozeroy",
                fillcolor: `${config.primaryColor}15`,
              },
            ];
        break;

      case "bar":
        plotlyData = chart.series
          ? chart.series.map((s) => ({ 
              x: chart.xAxis, 
              y: s.values, 
              type: "bar", 
              name: s.name,
              marker: { line: { width: 1, color: "#ffffff" } }
            }))
          : [{ 
              x: chart.labels, 
              y: chart.values, 
              type: "bar", 
              marker: { 
                color: config.primaryColor,
                line: { width: 1, color: "#ffffff" }
              }
            }];
        break;

      case "pie":
        plotlyData = [
          {
            labels: chart.labels,
            values: chart.values,
            type: "pie",
            hole: 0.5,
            marker: { 
              colors: generateColorPalette(chart.labels.length),
              line: { color: "#ffffff", width: 2 }
            },
            textinfo: "label+percent",
            textposition: "outside",
            textfont: { size: 13 },
          },
        ];
        break;

      case "stacked":
        if (!chart.series) return;
        plotlyData = chart.series.map((s, i) => ({
          x: chart.xAxis,
          y: s.values,
          type: "bar",
          name: s.name,
          marker: { 
            color: generateColorPalette(chart.series.length)[i],
            line: { width: 1, color: "#ffffff" }
          },
        }));
        baseLayout.barmode = "stack";
        break;

      default:
        return;
    }

    const plotConfig = {
      responsive: true,
      displayModeBar: true,
      modeBarButtonsToRemove: ["lasso2d", "select2d", "autoScale2d"],
      displaylogo: false,
    };

    Plotly.newPlot(containerId, plotlyData, baseLayout, plotConfig);

    // Handle window resize for responsive charts
    window.addEventListener('resize', function() {
      Plotly.Plots.resize(containerId);
    });
  }

  function formatValue(value) {
    if (value === null || value === undefined) return "N/A";
    return typeof value === "number" ? value.toLocaleString() : String(value);
  }

  function generateColorPalette(count) {
    const colors = [
      config.primaryColor,
      config.accentColor,
      "#6366f1",
      "#8b5cf6",
      "#ec4899",
      "#f59e0b",
      "#10b981",
      "#06b6d4",
    ];
    return Array.from({ length: count }, (_, i) => colors[i % colors.length]);
  }

  function escapeHTML(str) {
    return String(str)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;");
  }

  return { init, addMetric, addChart, render, clear, switchView };
})();

(function() {
    'use strict';

    // Clear individual filter field
    window.clearField = function(btn) {
        const wrapper = btn.closest('.input-wrapper');
        if (!wrapper) return;

        const input = wrapper.querySelector('.filter-input');
        if (input) {
            input.value = '';
            input.focus();
            updateClearButton(wrapper);
        }
    };

    // Clear all filters
    window.clearAllFilters = function() {
        const form = document.getElementById('filterForm');
        if (form) {
            form.reset();
            const wrappers = document.querySelectorAll('.input-wrapper');
            wrappers.forEach(function(wrapper) {
                updateClearButton(wrapper);
            });
        }
    };

    // Update clear button visibility
    function updateClearButton(wrapper) {
        const input = wrapper.querySelector('.filter-input');
        if (input && input.value && input.value.trim() !== '') {
            wrapper.classList.add('has-value');
        } else {
            wrapper.classList.remove('has-value');
        }
    }

    // Switch between dashboard and patient list views
    window.switchView = function(view) {
        document.getElementById('view-dashboard').classList.toggle('hidden', view !== 'dashboard');
        document.getElementById('view-list').classList.toggle('hidden', view !== 'list');
        document.getElementById('tab-dashboard').classList.toggle('active', view === 'dashboard');
        document.getElementById('tab-list').classList.toggle('active', view === 'list');

        if (view === 'dashboard' && typeof DashboardFramework !== 'undefined') {
            DashboardFramework.render();
        }
    };

    // Toggle sidebar collapse
    window.toggleSidebar = function() {
        const sidebar = document.querySelector('.sidebar');
        if (sidebar) {
            sidebar.classList.toggle('collapsed');

            // Save state to localStorage
            const isCollapsed = sidebar.classList.contains('collapsed');
            try {
                localStorage.setItem('sidebarCollapsed', isCollapsed ? '1' : '0');
            } catch(e) {
                // Ignore localStorage errors
            }
        }
    };

    // Toggle user dropdown
    window.toggleUserDropdown = function() {
        const menu = document.getElementById('userDropdownMenu');
        if (menu) {
            menu.classList.toggle('show');
        }
    };

    // Handle logout
    window.handleLogout = function() {
        if (confirm('Are you sure you want to logout?')) {
            window.location.href = '/csp/sys/UtilHome.csp?$NAMESPACE=%SYS&$1=';
        }
    };

    // Toggle MRN show more/less
    window.toggleMrn = function(id, elem) {
        const hiddenDiv = document.getElementById(id);
        if (!hiddenDiv) return;

        if (hiddenDiv.classList.contains('hidden')) {
            hiddenDiv.classList.remove('hidden');
            elem.innerHTML = 'Show Less';
        } else {
            hiddenDiv.classList.add('hidden');
            const count = hiddenDiv.children.length;
            elem.innerHTML = '+ ' + count + ' more';
        }
    };

    // Open patient viewer
    window.openViewer = function(hsaaid) {
        if (!hsaaid) {
            alert("Patient ID not provided");
            return;
        }

        const btn = event.target;
        btn.disabled = true;
        btn.innerHTML = 'Loading...';

        setTimeout(function() {
            const url = 'https://hcv.riayati.ae/csp/provider-portal/PCS.Riayati.SSO.ViewerV2.ProviderPortalHomePage.cls?id=' + hsaaid;
            window.open(url, '_blank');
            btn.disabled = false;
            btn.innerHTML = 'View';
        }, 500);
    };

    // UISwap for dashboard skeleton
    window.UISwap = {
        loading: function() {
            const skel = document.getElementById('skel-dashboard');
            const panel = document.getElementById('df-dashboard-panel');
            if (skel) skel.classList.remove('hidden');
            if (panel) panel.classList.add('hidden');
        },
        ready: function() {
            const skel = document.getElementById('skel-dashboard');
            const panel = document.getElementById('df-dashboard-panel');
            if (skel) skel.classList.add('hidden');
            if (panel) panel.classList.remove('hidden');
        }
    };

    // Confirm DateTime
    window.confirmDateTime = function(btn) {
        const wrapper = btn.closest('.input-wrapper');
        if (!wrapper) return;

        const input = wrapper.querySelector('.datetime-input');
        if (input && input.value) {
            btn.style.background = '#10b981';
            setTimeout(function() {
                btn.style.background = '#009CA6';
            }, 300);

            console.log('DateTime confirmed:', input.value);
        } else {
            alert('Please select a date and time first');
        }
    };

    // Close dropdown when clicking outside
    document.addEventListener('click', function(e) {
        if (!e.target.closest('.user-dropdown')) {
            const menu = document.getElementById('userDropdownMenu');
            if (menu) menu.classList.remove('show');
        }
    });

    // MODERN TOAST NOTIFICATION SYSTEM
    window.showToast = function(message, type, duration) {
        type = type || 'info'; // success, error, warning, info
        duration = duration || 4000; // 4 seconds default

        // Create toast container if doesn't exist
        let container = document.getElementById('toast-container');
        if (!container) {
            container = document.createElement('div');
            container.id = 'toast-container';
            container.className = 'toast-container';
            document.body.appendChild(container);
        }

        // Icon mapping
        const icons = {
            success: '?',
            error: '?',
            warning: '?',
            info: '?'
        };

        // Title mapping
        const titles = {
            success: 'Success',
            error: 'Error',
            warning: 'Warning',
            info: 'Information'
        };

        // Create toast element
        const toast = document.createElement('div');
        toast.className = `toast ${type}`;
        toast.innerHTML = `
            <div class="toast-icon">${icons[type]}</div>
            <div class="toast-content">
                <div class="toast-title">${titles[type]}</div>
                <div class="toast-message">${message}</div>
            </div>
            <button class="toast-close">×</button>
        `;

        container.appendChild(toast);

        // Close button handler
        const closeBtn = toast.querySelector('.toast-close');
        closeBtn.addEventListener('click', function() {
            removeToast(toast);
        });

        // Auto-remove after duration
        setTimeout(function() {
            removeToast(toast);
        }, duration);
    };

    function removeToast(toast) {
        toast.classList.add('hiding');
        setTimeout(function() {
            if (toast.parentNode) {
                toast.parentNode.removeChild(toast);
            }
        }, 300);
    }

    // Initialize on DOM ready
    document.addEventListener('DOMContentLoaded', function() {
        // Initialize clear button visibility
        const wrappers = document.querySelectorAll('.input-wrapper');
        wrappers.forEach(function(wrapper) {
            updateClearButton(wrapper);

            const input = wrapper.querySelector('.filter-input');
            if (input) {
                input.addEventListener('input', function() {
                    updateClearButton(wrapper);
                });
            }
        });

        // Restore sidebar state from localStorage
        try {
            const sidebarCollapsed = localStorage.getItem('sidebarCollapsed');
            if (sidebarCollapsed === '1') {
                const sidebar = document.querySelector('.sidebar');
                if (sidebar) sidebar.classList.add('collapsed');
            }
        } catch(e) {
            // Ignore localStorage errors
        }

        // Set dashboard as active tab
        if (typeof DashboardFramework !== 'undefined') {
            DashboardFramework.switchView('dashboard');

            const tabs = document.querySelectorAll('.df-nav-tab');
            tabs.forEach(function(tab) {
                const txt = (tab.textContent || '').toLowerCase();
                if (txt.includes('dashboard')) {
                    tab.classList.add('active');
                } else {
                    tab.classList.remove('active');
                }
            });
        }
    });

})();

(function() {
    'use strict';

    const MOCK_MODE = false;
    const MOCK_TOTAL_RECORDS = 900;
    const MOCK_DELAY = 1200;
    const DEBOUNCE_DELAY = 500;

    let lastRowId = '';
    let recordsPerPage = 150;
    let isLoading = false;
    let hasMoreData = true;
    let startIndex = 1;
    let mockCurrentId = 10000;
    let initialLoadDone = false;
    let hasExistingData = false;
    let applyFiltersTimeout = null;

    let currentFilters = {
        ProgramId: '',
        MPIID: '',
        FromTime: '',
        MRN: '',
        AssigningAuthority: ''
    };

    function generateMockRows(count, startIdx, lastId) {
        const names = [
            'Ahmed Ali Hassan', 'Fatima Mohammed Khan', 'Sara Abdullah Ibrahim',
            'Omar Hassan Yusuf', 'Aisha Ahmed Salem', 'Mohammed Ali Rashid',
            'Layla Hassan Omar', 'Khalid Ibrahim Said', 'Noor Fatima Ali',
            'Yusuf Mohammed Hassan', 'Mariam Ali Abdullah', 'Abdullah Omar Said'
        ];
        const genders = ['M', 'F'];
        const facilities = ['HAAD', 'DOH', 'MOH', 'DHA', 'SEHA'];

        let html = '';
        let currentRowId = lastId ? parseInt(lastId) : mockCurrentId;
        let recordsLeft = MOCK_TOTAL_RECORDS - (startIdx - 1);
        let actualCount = Math.min(count, recordsLeft);

        for (let i = 0; i < actualCount; i++) {
            currentRowId += Math.floor(Math.random() * 10) + 1;

            const idx = startIdx + i;
            const name = names[i % names.length];
            const gender = genders[i % 2];
            const month = String((i % 12) + 1).padStart(2, '0');
            const day = String((i % 28) + 1).padStart(2, '0');
            const dob = `198${(i % 10)}-${month}-${day}`;
            const mpiid = 'MPI' + (100000 + idx);
            const hsaaid = 'HSA' + (500000 + idx);
            const mrn = 'MRN' + (200000 + idx);
            const facility = facilities[i % facilities.length];
            const fromDate = `2024-${String((i % 12) + 1).padStart(2, '0')}-${String((i % 28) + 1).padStart(2, '0')}`;

            const genderRaw = genders[i % 2];
            const genderBadge = genderRaw === 'M' 
                ? '<span class="gender-badge male">M</span>' 
                : '<span class="gender-badge female">F</span>';

            html += `<tr data-sno="${idx}" class="fade-in">`;
            html += `<td>${idx}</td>`;
            html += `<td><strong>${name}</strong></td>`;
            html += `<td>${dob}</td>`;
            html += `<td>${genderBadge}</td>`;
            html += `<td>${mpiid}</td>`;
            html += `<td><div class="mrn-badge"><span class="mrn-val">${mrn}</span> <span class="aa-val">[${facility}]</span></div></td>`;
            html += `<td><span class="text-muted">${fromDate}</span></td>`;
            html += `<td align="center"><button type="button" class="btn-view" onclick="openViewer('${hsaaid}')">View</button></td>`;
            html += `</tr>`;
        }

        if (actualCount > 0) {
            html += `<input type="hidden" id="lastRowId" value="${currentRowId}">`;
        }

        return {
            html: html,
            hasMore: (startIdx + actualCount - 1) < MOCK_TOTAL_RECORDS
        };
    }

    function resetTable() {
        const tbody = document.getElementById('patientTableBody');
        if (tbody) tbody.innerHTML = '';

        hideElements(['msg-welcome', 'msg-no-data']);
        showElement('table-wrapper');
        resetSentinel();
    }

    function hideElements(ids) {
        ids.forEach(function(id) {
            const el = document.getElementById(id);
            if (el) el.classList.add('hidden');
        });
    }

    function showElement(id) {
        const el = document.getElementById(id);
        if (el) el.classList.remove('hidden');
    }

    function resetSentinel() {
        const sentinel = document.getElementById('loadSentinel');
        if (sentinel) {
            sentinel.innerHTML = '<span style="color:#009CA6; font-weight:600;">Scroll to load more...</span>';
        }
    }

    function validateFilters() {
        const form = document.getElementById('filterForm');
        const formData = new FormData(form);

        const programId = formData.get('ProgramId') || '';
        const mpiid = formData.get('MPIID') || '';
        const fromTime = formData.get('FromTime') || '';
        const mrn = formData.get('MRN') || '';
        const authority = formData.get('AssigningAuthority') || '';

        if (!programId && !mpiid && !fromTime && !mrn && !authority) {
            if (typeof showToast === 'function') {
                showToast('Please select at least one filter before applying. This prevents loading all records from the database.', 'warning', 5000);
            } else {
                alert('?? Please select at least one filter before applying.\n\nThis prevents loading all records from the database.');
            }
            return false;
        }

        return true;
    }

    window.applyFilters = function() {
        if (applyFiltersTimeout) {
            clearTimeout(applyFiltersTimeout);
        }

        if (!validateFilters()) {
            return;
        }

        applyFiltersTimeout = setTimeout(function() {
            executeApplyFilters();
        }, DEBOUNCE_DELAY);
    };

    function executeApplyFilters() {
        if (isLoading) {
            console.log('Load in progress, ignoring filter request');
            return;
        }

        const form = document.getElementById('filterForm');
        const formData = new FormData(form);

        currentFilters.ProgramId = formData.get('ProgramId') || '';
        currentFilters.MPIID = formData.get('MPIID') || '';
        currentFilters.FromTime = formData.get('FromTime') || '';
        currentFilters.MRN = formData.get('MRN') || '';
        currentFilters.AssigningAuthority = formData.get('AssigningAuthority') || '';

        recordsPerPage = parseInt(formData.get('RecordsPerPage')) || 150;

        const tbody = document.getElementById('patientTableBody');
        hasExistingData = tbody && tbody.querySelectorAll('tr[data-sno]').length > 0;

        lastRowId = '';
        startIndex = 1;
        hasMoreData = true;
        mockCurrentId = 10000;
        isLoading = false;

        lockControls(true);

        // FIX: Show skeletons IMMEDIATELY before any async operations
        if (hasExistingData) {
            showLoadingOverlay();
        } else {
            resetTable();
            showSkeletonRows(10); // Increased from 5 to 10
        }

        // Show dashboard skeleton IMMEDIATELY
        UISwap.loading();

        // Now load data
        initialLoadDone = true;
        loadNextBatch(true);

        const filterJSON1 = JSON.stringify(currentFilters);
        updateDashboardTab(filterJSON1);
    }

    function loadNextBatch(updateDashboard) {
        updateDashboard = updateDashboard || false;

        if (isLoading || !hasMoreData) {
            console.log('Skipping load - isLoading:', isLoading, 'hasMoreData:', hasMoreData);
            return;
        }

        isLoading = true;
        console.log('Loading batch - startIndex:', startIndex, 'lastRowId:', lastRowId, 'updateDashboard:', updateDashboard);

        if (MOCK_MODE) {
            setTimeout(function() {
                const mockData = generateMockRows(recordsPerPage, startIndex, lastRowId);

                removeSkeletonRows();
                hideLoadingOverlay();
                lockControls(false);

                if (mockData.html && mockData.html.trim() !== '') {
                    const tbody = document.getElementById('patientTableBody');
                    if (tbody) {
                        const oldHiddenFields = tbody.querySelectorAll('#lastRowId');
                        oldHiddenFields.forEach(field => field.remove());

                        if (hasExistingData && startIndex === 1) {
                            tbody.innerHTML = mockData.html;
                        } else {
                            tbody.insertAdjacentHTML('beforeend', mockData.html);
                        }
                    }

                    lastRowId = document.getElementById('lastRowId')?.value || lastRowId;

                    const rows = tbody.querySelectorAll('tr[data-sno]');
                    startIndex = rows.length + 1;

                    hasMoreData = mockData.hasMore;
                    hasExistingData = true;

                    updateLoadedCount();

                    if (!hasMoreData) {
                        showNoMoreMessage();
                    }
                } else {
                    showNoDataMessage();
                }

                isLoading = false;
            }, MOCK_DELAY);

        } else {
            try {
                const filterJSON = JSON.stringify(currentFilters);
                const htmlRows = getpatientList(lastRowId, recordsPerPage, startIndex, filterJSON, updateDashboard);

                removeSkeletonRows();
                hideLoadingOverlay();
                lockControls(false);

                if (htmlRows && htmlRows.trim() !== '') {
                    const tbody = document.getElementById('patientTableBody');
                    if (tbody) {
                        const oldHiddenFields = tbody.querySelectorAll('#lastRowId');
                        oldHiddenFields.forEach(field => field.remove());

                        if (hasExistingData && startIndex === 1) {
                            tbody.innerHTML = htmlRows;
                        } else {
                            tbody.insertAdjacentHTML('beforeend', htmlRows);
                        }
                    }

                    const newLastRowId = document.getElementById('lastRowId')?.value;

                    if (!newLastRowId || newLastRowId === '' || isNaN(newLastRowId)) {
                        console.error('ERROR: Invalid lastRowId returned from server:', newLastRowId);
                        showErrorMessage();
                        hasMoreData = false;
                        isLoading = false;
                        return;
                    }

                    if (newLastRowId === lastRowId && lastRowId !== '') {
                        console.warn('WARNING: lastRowId did not change. End of data.');
                        hasMoreData = false;
                        showNoMoreMessage();
                        isLoading = false;
                        return;
                    }

                    lastRowId = newLastRowId;

                    const rows = tbody.querySelectorAll('tr[data-sno]');
                    const previousCount = startIndex - 1;
                    const newCount = rows.length;
                    const rowsAdded = newCount - previousCount;

                    startIndex = rows.length + 1;
                    hasExistingData = true;

                    updateLoadedCount();

                    if (rowsAdded < recordsPerPage) {
                        hasMoreData = false;
                        showNoMoreMessage();
                        console.log('End of data - loaded', rowsAdded, 'rows (expected', recordsPerPage + ')');
                    }

                } else {
                    showNoDataMessage();
                }

            } catch (ex) {
                removeSkeletonRows();
                hideLoadingOverlay();
                lockControls(false);
                console.error('Error loading next batch:', ex);
                showErrorMessage();
                hasMoreData = false;
            }

            isLoading = false;
        }
    }

    function showNoDataMessage() {
        hasMoreData = false;
        const tbody = document.getElementById('patientTableBody');
        const hasRows = tbody && tbody.querySelectorAll('tr[data-sno]').length > 0;

        if (hasRows) {
            showNoMoreMessage();
        } else {
            hideElements(['table-wrapper', 'msg-welcome']);
            showElement('msg-no-data');
        }
    }

    function showNoMoreMessage() {
        hasMoreData = false;
        const sentinel = document.getElementById('loadSentinel');
        if (sentinel) {
            const tbody = document.getElementById('patientTableBody');
            const totalLoaded = tbody ? tbody.querySelectorAll('tr[data-sno]').length : 0;
            sentinel.innerHTML = `<span style="color:#64748b; font-weight:500;">? All ${totalLoaded} records loaded</span>`;
        }
    }

    function updateLoadedCount() {
        const sentinel = document.getElementById('loadSentinel');
        if (sentinel && hasMoreData) {
            const tbody = document.getElementById('patientTableBody');
            const totalLoaded = tbody ? tbody.querySelectorAll('tr[data-sno]').length : 0;
            sentinel.innerHTML = `<span style="color:#009CA6; font-weight:600;">?? Loaded ${totalLoaded} records - Scroll for more...</span>`;
        }
    }

    function showErrorMessage() {
        const sentinel = document.getElementById('loadSentinel');
        if (sentinel) {
            sentinel.innerHTML = '<span style="color:#e53e3e; font-weight:500;">? Error loading data</span>';
        }
    }

    function showSkeletonRows(count) {
        const tbody = document.getElementById('patientTableBody');
        if (!tbody) return;

        for (let i = 0; i < count; i++) {
            const skeletonRow = document.createElement('tr');
            skeletonRow.className = 'skeleton-row';
            skeletonRow.innerHTML = `
                <td><div class="skeleton txt-skel" style="width:40%;"></div></td>
                <td><div class="skeleton txt-skel"></div></td>
                <td><div class="skeleton txt-skel" style="width:60%;"></div></td>
                <td><div class="skeleton txt-skel" style="width:40%;"></div></td>
                <td><div class="skeleton txt-skel" style="width:80%;"></div></td>
                <td><div class="skeleton txt-skel"></div></td>
                <td><div class="skeleton txt-skel" style="width:70%;"></div></td>
                <td><div class="skeleton txt-skel" style="width:50%;"></div></td>
            `;
            tbody.appendChild(skeletonRow);
        }

        const sentinel = document.getElementById('loadSentinel');
        if (sentinel) {
            sentinel.innerHTML = '<span style="color:#009CA6; font-weight:600;">? Loading records...</span>';
        }
    }

    function removeSkeletonRows() {
        const skeletonRows = document.querySelectorAll('.skeleton-row');
        skeletonRows.forEach(function(row) {
            row.remove();
        });
    }

    function showLoadingOverlay() {
        const content = document.querySelector('#view-list');
        if (content) {
            content.classList.add('loading-overlay');
        }
    }

    function hideLoadingOverlay() {
        const content = document.querySelector('#view-list');
        if (content) {
            content.classList.remove('loading-overlay');
        }
    }

    function lockControls(lock) {
        const form = document.getElementById('filterForm');
        if (!form) return;

        const inputs = form.querySelectorAll('input, select, button');
        inputs.forEach(function(input) {
            input.disabled = lock;
        });

        const searchBtn = document.querySelector('.btn-search');
        if (searchBtn) {
            if (lock) {
                searchBtn.classList.add('loading');
            } else {
                searchBtn.classList.remove('loading');
            }
        }
    }

    function initLazyLoad() {
        const sentinel = document.getElementById('loadSentinel');
        if (!sentinel) return;

        const scrollContainer = document.getElementById('scrollContainer');

        const observer = new IntersectionObserver(
            function(entries) {
                entries.forEach(function(entry) {
                    if (entry.isIntersecting && !isLoading && hasMoreData && initialLoadDone) {
                        console.log('Sentinel visible - loading next batch...');
                        loadNextBatch(false);
                    }
                });
            },
            {
                root: scrollContainer,
                rootMargin: '100px',
                threshold: 0.1
            }
        );

        observer.observe(sentinel);
        console.log('Lazy load observer initialized');
    }

    window.changeRecordsPerPage = function() {
        if (isLoading) {
            console.log('Load in progress, ignoring records per page change');
            return;
        }

        const select = document.getElementById('recordsPerPageSelect');
        if (!select) return;

        recordsPerPage = parseInt(select.value) || 150;

        lastRowId = '';
        hasMoreData = true;
        startIndex = 1;
        mockCurrentId = 10000;
        isLoading = false;

        resetTable();
        showSkeletonRows(10);

        setTimeout(function() {
            initialLoadDone = true;
            loadNextBatch(false);
        }, 50);
    };

    document.addEventListener('DOMContentLoaded', function() {
        initLazyLoad();
        console.log('Table lazy load module initialized - Mock Mode:', MOCK_MODE);
    });

})();
